#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
const uint8_t players[4] = {2, 3, 7, 8};
unsigned long totals[4] = {0, 0, 0, 0};
bool locked = false;
bool resetHeld = false;
bool cleared = false;
unsigned long resetStart = 0;
uint8_t rawState[5];
uint8_t stableState[5];
unsigned long changedAt[5];

uint8_t inputPin(uint8_t i) { return i < 4 ? players[i] : 9; }

void resetRound() {
  locked = false;
  display.clear();
  digitalWrite(13, LOW);
  noTone(6);
}

void setup() {
  Serial.begin(9600);
  for (uint8_t i = 0; i < 5; ++i) {
    pinMode(inputPin(i), INPUT_PULLUP);
    rawState[i] = stableState[i] = HIGH;
    changedAt[i] = 0;
  }
  pinMode(13, OUTPUT);
  pinMode(6, OUTPUT);
  display.setBrightness(7);
  resetRound();
}

void loop() {
  unsigned long now = millis();
  bool pressed[5] = {false, false, false, false, false};
  for (uint8_t i = 0; i < 5; ++i) {
    uint8_t v = digitalRead(inputPin(i));
    if (v != rawState[i]) {
      rawState[i] = v;
      changedAt[i] = now;
    }
    if (v != stableState[i] && now - changedAt[i] >= 25) {
      stableState[i] = v;
      pressed[i] = (v == LOW);
    }
  }
  if (pressed[4]) {
    resetHeld = true;
    resetStart = now;
    cleared = false;
    resetRound();
  }
  if (resetHeld && stableState[4] == HIGH) resetHeld = false;
  if (resetHeld) {
    if (!cleared && now - resetStart >= 3000) {
      for (uint8_t i = 0; i < 4; ++i) totals[i] = 0;
      cleared = true;
    }
    return;
  }
  if (locked) return;
  for (uint8_t i = 0; i < 4; ++i) {
    if (pressed[i]) {
      locked = true;
      ++totals[i];
      display.showNumberDec(i + 1, false);
      digitalWrite(13, HIGH);
      tone(6, 1800, 120);
      Serial.print("timestamp_ms=");
      Serial.print(now);
      Serial.print(" player=");
      Serial.println(i + 1);
      break;
    }
  }
}
